package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class OperationsServiceTest {
 @Test void stationReservationSessionPaymentFlowPersists() throws Exception {Path p=Files.createTempFile("ops-", ".db");try(Database db=new Database(p)){UserService us=new UserService(db);us.bootstrap("m","password1");var manager=us.authenticate("m","password1");var u=us.registerCustomer("Ops Customer","ops@example.com","03001234001","password2");OperationsService o=new OperationsService(db);long station=o.addStation(manager.id(),"PC-01","PC","",50000);long reservation=o.reserve(u.id(),station,Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200));long session=o.startSession(manager.id(),reservation);o.finishSession(manager.id(),session,12500);long payment=o.settleSession(u.id(),session,12500,"CASH","receipt-1");assertTrue(station>0&&reservation>0&&session>0&&payment>0);assertEquals(1,o.reportCount("payments"));assertThrows(IllegalStateException.class,()->o.reserve(u.id(),station,Instant.now().plusSeconds(4000),Instant.now().plusSeconds(5000)));}finally{Files.deleteIfExists(p);}}
}
